164: function createTrack(stageIndex) {
165:   const stage = stageConfigs[stageIndex];
166:   const points = [];
167:   const total = 1600;
168:   const curves = stage.track.curves;
169:   for (let i = 0; i <= total; i += 1) {
170:     const t = i / total;
171:     let center = 0;
172:     for (const curve of curves) {
173:       center += Math.sin(t * (Math.PI * 2.2) * curve.freq + curve.phase) * curve.amplitude * (1 / (curves.length * 0.9));
174:     }
175:     const x = t * (stage.track.roadWidth * 1.3);
176:     const y = center + (Math.sin(t * 18 + stageIndex) * 18);
177:     points.push({ x, y, t });
178:   }
179: 
180:   const checkpoints = [];
181:   const checkpointCount = 5;
182:   for (let i = 0; i < checkpointCount; i += 1) {
183:     const t = (i + 1) / checkpointCount;
184:     checkpoints.push({ t, x: t * 100, y: 0 });
185:   }
186: 
187:   const road = [];
188:   for (let i = 0; i <= total; i += 1) {
189:     const p = points[i];
190:     const multiplier = (i / total) * 1.2 + 0.35;
191:     const width = stage.track.roadWidth * multiplier;
192:     const segment = {
193:       x: p.x,
194:       y: p.y,
195:       width,
196:       t: p.t,
197:       angle: Math.atan2((points[Math.min(i + 1, total)].y - p.y), 0.7),
198:     };
199:     road.push(segment);
200:   }
201: 
202:   TrackHelper.buildRuntimeRoad(stage, road, checkpoints);
203:   track.totalDistance = total;
204:   track.checkpoints = checkpoints;
205:   track.road = road;
206: }
