211:     for (let i = 0; i < checkpoints.length; i += 1) {
212:       const cp = checkpoints[i];
213:       const index = Math.floor(cp.t * (road.length - 1));
214:       cp.x = road[index].x;
215:       cp.y = road[index].y;
216:       cp.width = roadWidthBase * (0.8 + i * 0.12);
217:       cp.angle = road[index].angle;
218:     }
