593: function drawRoad() {
594:   const width = canvas.clientWidth;
595:   const height = canvas.clientHeight;
596:   const road = track.road;
597:   if (!road.length) return;
598: 
599:   const viewStart = Math.max(0, state.car.routeProgress - 50);
600:   const viewEnd = Math.min(track.totalDistance * state.totalLaps, state.car.routeProgress + 220);
601:   const worldToScreen = (progress, offset) => {
602:     const x = ((progress - viewStart) / (viewEnd - viewStart)) * width;
603:     const roadCurve = getRoadAt(progress).x;
604:     const y = height * 0.62 + (offset * 0.7) + (roadCurve * 0.2);
605:     return { x, y };
606:   };
607: 
608:   ctx.beginPath();
609:   ctx.moveTo(0, height);
610:   for (let i = 0; i <= 120; i += 1) {
611:     const progress = lerp(viewStart, viewEnd, i / 120);
612:     const p = getRoadAt(progress);
613:     const x = ((progress - viewStart) / (viewEnd - viewStart)) * width;
614:     const y = height * 0.62 + (p.y * 0.7);
615:     if (i === 0) ctx.moveTo(x, y);
616:     ctx.lineTo(x, y);
617:   }
618:   ctx.lineTo(width, height);
619:   ctx.closePath();
620:   ctx.fillStyle = 'rgba(38, 39, 37, 0.96)';
621:   ctx.fill();
622: 
623:   for (let i = 0; i < 90; i += 1) {
624:     const progress = lerp(viewStart, viewEnd, i / 90);
625:     const p = getRoadAt(progress);
626:     const x = ((progress - viewStart) / (viewEnd - viewStart)) * width;
627:     const y = height * 0.62 + (p.y * 0.7);
628:     ctx.fillStyle = i % 2 ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.18)';
629:     ctx.fillRect(x - 4, y - 18, 8, 36);
630:   }
631: 
632:   const carScreenX = width * 0.5;
633:   const carScreenY = height * 0.64 + state.car.y * 0.08;
634:   const carRotation = state.car.heading;
635:   const carLength = 40;
636:   const carWidth = 18;
637:   ctx.save();
638:   ctx.translate(carScreenX, carScreenY);
639:   ctx.rotate(carRotation);
640:   ctx.fillStyle = '#f6f6f6';
641:   ctx.fillRect(-carLength / 2, -carWidth / 2, carLength, carWidth);
642:   ctx.fillStyle = '#d24d44';
643:   ctx.fillRect(carLength / 2 - 8, -carWidth / 2 + 3, 10, carWidth - 6);
644:   ctx.fillStyle = '#1c1f1f';
645:   ctx.fillRect(-carLength / 2 + 6, -carWidth / 2 + 3, 18, 4);
646:   ctx.fillRect(-carLength / 2 + 6, carWidth / 2 - 7, 18, 4);
647:   ctx.restore();
648: }
