650: function drawParticles() {
651:   for (let i = state.particles.length - 1; i >= 0; i -= 1) {
652:     const p = state.particles[i];
653:     p.x += p.vx;
654:     p.y += p.vy;
655:     p.life -= 1;
656:     ctx.fillStyle = p.color.replace(')', `, ${clamp(p.life / 60, 0, 1)})`).replace('rgb', 'rgba');
657:     ctx.fillRect(p.x, p.y, p.size, p.size);
658:     if (p.life <= 0) state.particles.splice(i, 1);
659:   }
660: }
